'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Sliders, SlidersHorizontal, Play, FileText } from 'lucide-react';
import { PageHeader, TabNav, ConfirmDialog, usePersistentState, type TabItem } from '@gateway-experience/shared';
import type { ScoreRuleset } from '../types';
import { deleteRuleset, listRulesets, saveRuleset } from '../api';

import { RulesetsTab } from './tabs/RulesetsTab';
import { BlendingTab } from './tabs/BlendingTab';
import { ScoreSimulatorTab } from './tabs/ScoreSimulatorTab';
import { RulesetModal } from './modals/RulesetModal';

export const ScoreManager: React.FC = () => {
  const [activeTab, setActiveTab] = usePersistentState<'rulesets' | 'blending' | 'simulator'>('xg.scoreEngine.activeTab', 'rulesets');
  const [searchQuery, setSearchQuery] = useState('');

  // Rulesets Data
  const [rulesets, setRulesets] = useState<ScoreRuleset[]>([]);
  // Selection is kept by id (and survives a reload); the object is always
  // the freshly loaded one. Tabs fall back to the first ruleset when unset.
  const [selectedRulesetId, setSelectedRulesetId] = usePersistentState<string | null>('xg.scoreEngine.selectedRulesetId', null);
  const selectedRuleset = rulesets.find((r) => r.id === selectedRulesetId) ?? null;
  const setSelectedRuleset = (r: ScoreRuleset | null) => setSelectedRulesetId(r?.id ?? null);

  // Modals Visibility
  const [isRulesetModalOpen, setIsRulesetModalOpen] = useState(false);
  const [editingRuleset, setEditingRuleset] = useState<ScoreRuleset | null>(null);

  // Confirm Delete Dialog State
  const [deleteConfirm, setDeleteConfirm] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    isLoading?: boolean;
    onConfirm: () => void | Promise<void>;
  }>({
    isOpen: false,
    title: '',
    message: '',
    isLoading: false,
    onConfirm: () => {},
  });

  const loadRulesets = useCallback(() => {
    // The studio has no tenant selector: it lists every tenant's rulesets,
    // scoped explicitly so the gateway cannot narrow it to one brand.
    listRulesets()
      .then((list) => {
        if (list) setRulesets(list);
      })
      .catch(() => {});
  }, []);

  useEffect(() => {
    loadRulesets();
  }, [loadRulesets]);

  const scoreTabs: TabItem[] = [
    {
      id: 'rulesets',
      label: 'Skin Grading',
      icon: <Sliders className="h-4 w-4" />,
      badge: rulesets.length,
    },
    {
      id: 'blending',
      label: 'Blending',
      icon: <SlidersHorizontal className="h-4 w-4" />,
    },
    {
      id: 'simulator',
      label: 'Simulator',
      icon: <Play className="h-4 w-4" />,
    },
  ];

  const handleSaveRuleset = async (rulesetData: Partial<ScoreRuleset>) => {
    await saveRuleset(rulesetData);
    loadRulesets();
  };

  const handleDeleteRuleset = (id: string, code: string) => {
    setDeleteConfirm({
      isOpen: true,
      title: 'Delete Skin Grading Framework',
      message: `Are you sure you want to delete skin grading framework "${code}"? This cannot be undone.`,
      onConfirm: async () => {
        setDeleteConfirm((prev) => ({ ...prev, isLoading: true }));
        try {
          await deleteRuleset(id);
          loadRulesets();
        } catch (err: any) {
          alert(err.message);
        } finally {
          setDeleteConfirm((prev) => ({ ...prev, isOpen: false, isLoading: false }));
        }
      },
    });
  };

  return (
    <div className="flex-1 min-w-0 h-full overflow-y-auto bg-background text-foreground font-sans flex flex-col select-none">
      {/* Studio Header */}
      <PageHeader
        icon={<FileText className="h-5 w-5" />}
        breadcrumbs={[
          { label: 'Workbench', href: '/api-client' },
          { label: 'Core Engines' },
          { label: 'Score Engine' },
        ]}
        title="Score Engine"
      >
        <TabNav
          tabs={scoreTabs}
          activeTab={activeTab}
          onTabChange={(id: string) => {
            setActiveTab(id as any);
            setSearchQuery('');
          }}
        />
      </PageHeader>

      {/* Main Content Area */}
      <main className="flex-1 p-4 sm:p-6 space-y-4 sm:space-y-6 max-w-7xl w-full mx-auto">
        {activeTab === 'rulesets' && (
          <RulesetsTab
            rulesets={rulesets}
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            onOpenCreateModal={() => {
              setEditingRuleset(null);
              setIsRulesetModalOpen(true);
            }}
            onOpenEditModal={(r) => {
              setEditingRuleset(r);
              setIsRulesetModalOpen(true);
            }}
            onSelectSimulatorRuleset={(r) => {
              setSelectedRuleset(r);
              setActiveTab('simulator');
            }}
            onDeleteRuleset={handleDeleteRuleset}
          />
        )}

        {activeTab === 'blending' && (
          <BlendingTab
            rulesets={rulesets}
            selectedRuleset={selectedRuleset}
            onSelectRuleset={setSelectedRuleset}
            onSaveRuleset={handleSaveRuleset}
          />
        )}

        {activeTab === 'simulator' && (
          <ScoreSimulatorTab
            rulesets={rulesets}
            selectedRuleset={selectedRuleset}
            onSelectRuleset={setSelectedRuleset}
          />
        )}
      </main>

      {/* Modals */}
      <RulesetModal
        isOpen={isRulesetModalOpen}
        onClose={() => setIsRulesetModalOpen(false)}
        onSave={handleSaveRuleset}
        editingRuleset={editingRuleset}
      />

      <ConfirmDialog
        isOpen={deleteConfirm.isOpen}
        title={deleteConfirm.title}
        message={deleteConfirm.message}
        onConfirm={deleteConfirm.onConfirm}
        onClose={() => setDeleteConfirm((prev) => ({ ...prev, isOpen: false }))}
      />
    </div>
  );
};
